This code defines a decorator function `ttl_cache` that takes in four parameters: `maxsize`, `ttl`, `timer`, and `typed`. The decorator returns a wrapper function that wraps the original function `func`. The wrapper function first checks if the arguments passed to the function are already in the cache and if the time-to-live (TTL) for the cached value has not expired. If the value is in the cache and the TTL has not expired, the cached value is returned. Otherwise, the function is called and the result is stored in the cache with the current timestamp. The cache is implemented as a dictionary where the keys are the function arguments and the values are tuples of the function result and the timestamp. The `typed` parameter is not used in this implementation.

def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            key = args + tuple(kwargs.items())
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem()
            return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        def inner(*args, **kwargs):
            key = args + tuple(kwargs.items())
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.pop(next(iter(cache)))
            return result
        return inner
    return wrapper

