def validate_version_inventories(self, version_dirs):
    # Initialize variables
    root_inventory = None
    previous_inventory = None
    digest_mismatches = []

    # Iterate through the version directories
    for version_dir in version_dirs:
        # Get the inventory for the current version
        inventory = self.get_inventory(version_dir)

        # Check if the inventory is valid
        if not inventory.is_valid():
            return False

        # Check if the inventory is up to date
        if root_inventory and not inventory.is_up_to_date(root_inventory):
            return False

        # Check if the inventory has any content digests that are different from those in the root inventory
        if previous_inventory:
            for digest in inventory.digests():
                if digest not in previous_inventory.digests():
                    digest_mismatches.append(digest)

        # Update the previous inventory and root inventory
        previous_inventory = inventory
        if not root_inventory:
            root_inventory = inventory

    # Check if there are any digest mismatches
    if digest_mismatches:
        return False

    return True

