def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append("Candidate does not provide interface")

    for name, method in iface.namesAndDescriptions():
        if not hasattr(candidate, name):
            errors.append(f"Candidate does not define method {name}")
        else:
            candidate_method = getattr(candidate, name)
            if not inspect.ismethod(candidate_method):
                errors.append(f"Candidate defines {name} as a non-method")
            else:
                if not _signature_matches(method, candidate_method):
                    errors.append(f"Candidate defines {name} with incorrect signature")

    for name, attribute in iface.namesAndDescriptions(descriptor=True):
        if not hasattr(candidate, name):
            errors.append(f"Candidate does not define attribute {name}")
        else:
            candidate_attribute = getattr(candidate, name)
            if not isinstance(candidate_attribute, type(attribute)):
                errors.append(f"Candidate defines {name} as a {type(candidate_attribute).__name__}, expected {type(attribute).__name__}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid(", ".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    if not inspect.isclass(candidate):
        return False
    if not issubclass(candidate, iface):
        return False
    if tentative:
        return True
    for method in iface.__abstractmethods__:
        if not hasattr(candidate, method):
            return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = [base.__class__ for base in bases]
    if not metaclasses:
        return type
    else:
        metaclass = metaclasses[0]
        for cls in metaclasses[1:]:
            if not issubclass(cls, metaclass):
                raise TypeError("metaclass conflict: the metaclasses of the bases are "
                                "incompatible")
        return metaclass

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

